import React, { useState, useEffect } from 'react';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';
import Container from '@mui/material/Container';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import { blue, green } from '@mui/material/colors';
import { HashRouter as Router } from 'react-router-dom';
import ResumenFinanciero from './ResumenFinanciero';
import AgregarTransaccion from './AgregarTransaccion';
import ListaTransacciones from './ListaTransacciones';
import { db, ref, onValue, push, remove, update } from './firebaseConfig';

const theme = createTheme({
  palette: {
    primary: blue,
    secondary: green,
    mode: 'light',
  },
});

function App() {
  const [transacciones, setTransacciones] = useState([]);

  // Cargar transacciones desde Firebase al montar el componente
  useEffect(() => {
    const transaccionesRef = ref(db, 'transacciones');

    const unsubscribe = onValue(transaccionesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const transaccionesArray = Object.keys(data).map(key => ({
          id: key,
          ...data[key]
        }));
        setTransacciones(transaccionesArray);
      } else {
        setTransacciones([]);
      }
    });

    return () => unsubscribe();
  }, []);

  // Agregar transacción a Firebase
  const agregarTransaccion = (transaccion) => {
    const transaccionesRef = ref(db, 'transacciones');
    push(transaccionesRef, {
      descripcion: transaccion.descripcion,
      monto: transaccion.monto,
      tipo: transaccion.tipo,
      categoria: transaccion.categoria,
      fecha: transaccion.fecha
    });
  };

  // Eliminar transacción de Firebase
  const eliminarTransaccion = (id) => {
    const transaccionRef = ref(db, `transacciones/${id}`);
    remove(transaccionRef);
  };

  // Editar transacción en Firebase (opcional)
  const editarTransaccion = (id, nuevosDatos) => {
    const transaccionRef = ref(db, `transacciones/${id}`);
    update(transaccionRef, nuevosDatos);
  };

  return (
    <Router>
      <ThemeProvider theme={theme}>
        <CssBaseline />
        <AppBar position="static">
          <Toolbar>
            <Typography variant="h6" component="div" sx={{ flexGrow: 1, textAlign:'center'}}>
             Finanzas Diarias de Pablo
            </Typography>
          </Toolbar>
        </AppBar>
        <Container maxWidth="md" sx={{ mt: 4 }}>
          <Box sx={{ mb: 4 }}>
            <ResumenFinanciero transacciones={transacciones} />
          </Box>
          <Box sx={{ mb: 4 }}>
            <AgregarTransaccion onAgregarTransaccion={agregarTransaccion} />
          </Box>
          <Box>
            <ListaTransacciones
              transacciones={transacciones}
              onEliminarTransaccion={eliminarTransaccion}
            />
          </Box>
        </Container>
      </ThemeProvider>
    </Router>
  );
}

export default App;